"""compare_gripper_model.py: a run generated by the model itself must compare as a perfect fit."""

import csv
import json
import sys
from pathlib import Path

import numpy as np
import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[3] / "examples" / "gripper_force_control"))
import compare_gripper_model as cmp

MODEL = cmp.DirectionModel(tau_s=0.18, tau_c=0.15, damping=0.065, inertia=1.5e-3)
STROKE = 5.27


def _write_run(run: Path) -> None:
    """A tiny run: one breakaway and two torque steps per direction, generated by MODEL."""
    meta = {"stroke_rad": STROKE}
    fit = {
        "breakaway": {d: {"mean_nm": MODEL.tau_s} for d in ("close", "open")},
        "steps": {
            d: {"tau_c_kinetic": MODEL.tau_c, "total_damping": MODEL.damping, "inertia_kg_m2": MODEL.inertia}
            for d in ("close", "open")
        },
    }
    (run / "meta.json").write_text(json.dumps(meta))
    (run / "fit.json").write_text(json.dumps(fit))
    t = np.arange(0, 1.0, 0.004)
    samples, trials = [], []
    index = 0
    for d in ("close", "open"):
        sign = 1.0 if d == "close" else -1.0
        for kind, tq in (("breakaway", 0.6), ("step", 0.3), ("step", 0.5)):
            cmd_along = np.minimum(0.2 * t, tq) if kind == "breakaway" else np.full_like(t, tq)
            travel = cmp.simulate(MODEL, t, cmd_along)
            start = 0.5 if kind == "breakaway" else (0.92 if d == "close" else 0.08)
            s = start - sign * travel / STROKE
            for k in range(len(t)):
                samples.append([index, kind, d, t[k], s[k], 0.0, 0.0, sign * cmd_along[k]])
            trials.append(
                {
                    "trial": index,
                    "kind": kind,
                    "direction": d,
                    "start_s": start,
                    "repeat": 0,
                    "torque_nm": tq,
                    "breakaway_torque": MODEL.tau_s if kind == "breakaway" else "",
                    "reached_end": "True" if kind == "step" else "",
                    "steady_speed_rad_s": (tq - MODEL.tau_c) / MODEL.damping if kind == "step" else "",
                    "time_constant_s": MODEL.inertia / MODEL.damping if kind == "step" else "",
                }
            )
            index += 1
    with open(run / "samples.csv", "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["trial", "kind", "direction", "t_s", "s", "s_dot_per_s", "eff_closing_nm", "cmd_closing_nm"])
        w.writerows(samples)
    with open(run / "trials.csv", "w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=list(trials[0]))
        w.writeheader()
        w.writerows(trials)


def test_a_run_of_the_model_itself_compares_as_a_perfect_fit(tmp_path: Path) -> None:
    _write_run(tmp_path)
    meta, fit, trials = cmp.load_run(tmp_path)
    result = cmp.compare(meta, fit, trials)
    for row in result["rows"]:
        if row["kind"] == "breakaway":
            assert row["breakaway_error_nm"] == pytest.approx(0.0, abs=1e-9)
        else:
            assert row["travel_rms_error_rad"] == pytest.approx(0.0, abs=1e-9)
            assert row["speed_measured_rad_s"] == pytest.approx(row["speed_model_rad_s"])
    for direction in ("close", "open"):
        assert result["summary"][direction]["steady_speed_rms_error_rad_s"] == pytest.approx(0.0, abs=1e-9)


def test_main_writes_the_comparison(tmp_path: Path) -> None:
    _write_run(tmp_path)
    cmp.main(tmp_path)
    assert json.loads((tmp_path / "comparison" / "summary.json").read_text())["models"]["close"]["tau_c"] == 0.15
    assert (tmp_path / "comparison" / "trials.csv").exists()


def test_a_sweep_and_jaw_travel_run_without_steps_compares(tmp_path: Path) -> None:
    """Either new experiment can be a whole run: no torque steps, so no fitted model to simulate."""
    fit = {
        "breakaway": {},
        "steps": {},
        "sweep": {
            "positions": [0.3, 0.5, 0.7],
            "motor_angle_rad": [4.9, 3.9, 2.8],
            "close_nm": [0.22, 0.10, 0.12],
            "open_nm": [0.14, 0.20, 0.16],
            "friction_nm": [0.18, 0.15, 0.14],
            "offset_nm": [0.04, -0.05, -0.02],
            "friction_range_nm": [0.14, 0.18],
            "offset_range_nm": [-0.05, 0.04],
            "offset_period": None,
            "friction_period": None,
        },
        "jaw_travel": {
            "mm_per_rad": 18.2,
            "travel_over_calibrated_stroke_mm": 96.0,
            "linearity_rms_mm": 0.1,
            "force_map_error": -0.2,
            "suggested": {"gripper_stroke": 0.096, "motor_stroke": 5.27},
        },
    }
    (tmp_path / "meta.json").write_text(json.dumps({"stroke_rad": STROKE}))
    (tmp_path / "fit.json").write_text(json.dumps(fit))
    (tmp_path / "samples.csv").write_text("trial,kind,direction,t_s,s,s_dot_per_s,eff_closing_nm,cmd_closing_nm\n")
    (tmp_path / "trials.csv").write_text("trial,kind,direction,start_s,repeat,torque_nm\n")
    cmp.main(tmp_path)
    summary = json.loads((tmp_path / "comparison" / "summary.json").read_text())
    assert summary["sweep"]["offset_range_nm"] == [-0.05, 0.04]
    assert summary["jaw_travel"]["force_map_error"] == -0.2
